(window.FLIPCOPY_I18N = window.FLIPCOPY_I18N || {})["vi"] = {"nav.skip":"Chuyển đến nội dung","nav.home":"Trang chủ","nav.documentation":"Tài liệu","nav.changelog":"Nhật ký thay đổi","nav.download":"Tải xuống","hero.tagline":"Đặt lên mặt kính. Nhấn START. Kéo bản sao ra.","hero.sub":"Đưa âm thanh vào, MIDI ra. Đưa MIDI vào, âm thanh ra. Miễn phí, ngoại tuyến và 100% không dùng AI.","notice.price":"Freally Flipcopy hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","hero.chipStandalone":"Ứng dụng độc lập","hero.noDownloads":"Đang phát triển. Chưa có bản tải xuống nào cho đến phiên bản 1.0.0, và mã nguồn là riêng tư.","what.title":"Đây là gì","what.p1":"Biến một đoạn loop thành MIDI, hay một tệp MIDI thành âm thanh, thường có nghĩa là một chuỗi công cụ, một lần xuất, nhập lại và rất nhiều phỏng đoán về kết quả.","what.p2":"Flipcopy là một máy photocopy. Đặt một tệp âm thanh hoặc tệp MIDI lên mặt kính của nó, nó sẽ in ra bản gốc — dạng sóng thật, hoặc từng nốt nhạc cùng dữ liệu của nó. Nhấn nút START màu xanh lá, nó sẽ in ra bản sao ở dạng còn lại: đưa âm thanh vào, MIDI ra; đưa MIDI vào, âm thanh ra.","what.p3":"Bản sao ra dưới dạng một trang in với khung xanh chanh quanh đoạn clip. Cầm lấy khung và kéo nó vào một track trong DAW của bạn. Mỗi bản sao là một tệp thật, nằm nguyên tại chỗ, nên dự án của bạn không bao giờ mất nó.","see.title":"Xem nó sao chép","see.intro":"Máy photocopy, được dựng hình bằng Blender: bản gốc đặt xuống mặt kính, nắp đóng lại, đèn quét qua, và bản sao trượt ra khay.","see.audioToMidi":"Đưa âm thanh vào, MIDI ra: mỗi lớp một trang — giai điệu, hợp âm, bassline và giai điệu đối.","see.midiToAudio":"Đưa MIDI vào, âm thanh ra.","see.start":"Nhấn START để xem máy sao chép","features.title":"Bên trong có gì","features.copier.title":"Máy photocopy","features.copier.body":"Một máy photocopy được dựng hình chân thực bằng Blender. Đặt một clip lên mặt kính, nó sẽ in ra thứ thật: từng nốt nhạc, hoặc dạng sóng thật, cùng tempo, độ dài và mức âm lượng.","features.start.title":"Nút START màu xanh lá","features.start.body":"Thả một clip xuống chỉ đặt nó lên mặt kính. Không gì được sao chép cho đến khi bạn nhấn START, nên không có gì xảy ra ngoài ý muốn của bạn.","features.audioToMidi.title":"Âm thanh → MIDI","features.audioToMidi.body":"Trống, bass, giai điệu, giai điệu đối và hợp âm trong một loop, mỗi thứ một trang, in liền nhau từ một lần quét, để kéo vào DAW thành các track riêng.","features.midiToAudio.title":"MIDI → âm thanh","features.midiToAudio.body":"Một tệp MIDI được chơi qua một nhạc cụ thật, và trống qua một drum machine, in ra thành một tệp âm thanh bạn có thể kéo đi.","features.drag.title":"Kéo bản sao","features.drag.body":"Mỗi trang mang một khung xanh chanh quanh clip của nó. Cầm lấy và thả vào một track. Tệp là thật, và Flipcopy không bao giờ ghi đè hay xóa nó.","features.browser.title":"Trình duyệt","features.browser.body":"Một trình duyệt tệp có trình phát để nghe thử, từ Freally Oscillate. Nó hiện dạng sóng cho âm thanh và các nốt nhạc cho MIDI, và phát MIDI qua đúng nhạc cụ mà bản sao sử dụng.","features.daw.title":"Trong mọi DAW","features.daw.body":"CLAP, VST3 và AU, cùng một ứng dụng độc lập để làm việc không cần DAW và cho Pro Tools. Windows, macOS và Linux.","features.free.title":"Miễn phí, ngoại tuyến, không dùng AI","features.free.body":"Không có gói, không tài khoản, không đo lường từ xa, không mạng, không mô hình. Xử lý tín hiệu cổ điển, được một cổng kiểm tra khi dựng bảo đảm chứ không chỉ là lời hứa.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng. Đây là chính chiếc thang mà kế hoạch nội bộ đang theo — nếu một bên di chuyển, bên kia cũng di chuyển, và một cổng kiểm tra khi dựng sẽ đối chiếu chúng.","ladder.version":"Phiên bản","ladder.state":"Trạng thái","ladder.state.done":"Xong","ladder.state.planned":"Đã lên kế hoạch","ladder.state.goal":"Mục tiêu","ladder.state.later":"Về sau","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, cho âm thanh của bạn đi qua nguyên vẹn, đề nghị bạn chấp nhận giấy phép, và mọi cổng kiểm tra chất lượng đều chạy.","ladder.rung.v0.2.0":"Máy photocopy và bản sao đầu tiên: cỗ máy trong cửa sổ, nút START màu xanh lá, và một tệp MIDI được sao thành âm thanh để bạn kéo thẳng vào DAW.","ladder.rung.v0.3.0":"Âm thanh sang MIDI: đặt một loop lên mặt kính, nhấn START, rồi kéo trống, bass, giai điệu và hợp âm của nó ra dưới dạng MIDI.","ladder.rung.v0.4.0":"Trình duyệt tệp và trình phát nghe thử: tìm một sample hoặc clip MIDI, nghe, xem, rồi kéo nó lên mặt kính. Mọi thứ thiết yếu đều đã có.","ladder.rung.v0.5.0":"Màn hình cảm ứng: thiết lập sao chép, nhạc cụ cho các bản sao, định dạng tệp, và lịch sử của mọi bản sao bạn đã tạo.","ladder.rung.v0.5.5":"Studio: mở bất kỳ bản sao nào trong piano roll, sửa các nốt, nghe bằng bất kỳ nhạc cụ nào, và in bản chỉnh sửa thành một bản sao mới.","ladder.rung.v0.5.7":"Bàn trộn và nhạc cụ của riêng bạn: núm vặn chân thực để định hình từng phần, bộ trống và sample của riêng bạn, mục yêu thích, và một thư viện nhạc cụ dùng chung cho mọi ứng dụng Freally.","ladder.rung.v0.5.9":"Giao diện và chế độ sáng: năm giao diện, mỗi cái là một khung nổi được dựng bằng Blender và giống nhau trên mọi ứng dụng Freally, có bản sáng và tối, cùng một chế độ sáng mới.","ladder.rung.v0.6.0":"Trong mọi DAW: lưu cùng dự án, nhiều bản sao cùng lúc, quét trực tiếp từ một track, và được kiểm tra trên từng DAW.","ladder.rung.v0.7.0":"Ứng dụng độc lập với đầy đủ sức mạnh, macOS và Linux, cùng video máy photocopy đang hoạt động.","ladder.rung.v0.8.0":"Độ chính xác, độ chân thực và tốc độ: ký âm tốt hơn, cỗ máy thuyết phục hơn, và mọi ngân sách hiệu năng đều được thực thi.","ladder.rung.v1.0.0-beta":"Gia cố: trình cài đặt cho ba hệ điều hành, tính năng kiểm tra cập nhật tùy chọn, và cuốn sổ tay minh họa đầy đủ. Trang này vẫn chưa có bản tải xuống.","ladder.rung.v1.0.0-rc":"Bản ứng viên phát hành: mọi tệp đều được rà soát và mọi host đều được thử thủ công.","ladder.rung.v1.0.0":"Bản phát hành chính thức — và những bản tải xuống đầu tiên trang này từng cung cấp.","ladder.rung.v1.1.0":"Khay nạp bản gốc: sao chép cả một thư mục trong một lần.","ladder.rung.v1.3.0":"Bản sao dạng bản nhạc: MusicXML và bản in trên khuông nhạc.","ladder.rung.v1.4.0":"Cầu nối đến các sản phẩm Freally khác.","ladder.rung.v1.5.0":"Pro Tools dưới dạng plugin (AAX), nếu điều khoản của Avid cho phép với một sản phẩm miễn phí.","ladder.rung.v1.6.0":"Bản sao groove, và bản sao stem thô, không dùng AI.","ladder.lands":"Nó mang lại gì","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có, và sẽ không có cho đến 1.0.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.transcription.title":"Bản sao MIDI của một bản mix là một bản ký âm","honest.transcription.body":"Tìm nốt nhạc trong một bản mix đã hoàn thiện là việc khó, và Flipcopy làm điều đó bằng xử lý tín hiệu cổ điển thay vì một mô hình. Nó sẽ bỏ sót một số nốt và nghe ra một số nốt không thật sự có. Nó in ra những gì tìm được, và nói rõ những gì nó không làm được.","honest.chords.title":"Hợp âm quay lại dưới dạng một tiến trình hợp âm","honest.chords.body":"Một bè hợp âm được in ra như tiến trình hợp âm mà nó theo, chứ không phải cách bấm chính xác đã được chơi, và trang in nói rõ điều đó.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản dựng thử, không có quyền truy cập sớm. Một máy photocopy chạy nửa vời còn tệ hơn một máy chưa tồn tại.","honest.network.title":"Nó không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập hoàn toàn không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, mặc định tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Những bản sao bạn tạo ra là của bạn, miễn là các tệp bạn sao chép vốn thuộc quyền sử dụng của bạn. Tác giả của Flipcopy không nhận bất kỳ quyền sở hữu nào đối với chúng.","nav.language":"Ngôn ngữ","docs.title":"Tài liệu","docs.intro":"Tài liệu này lớn dần theo từng phiên bản. Hiện nó mô tả những gì phiên bản 0.2.0 làm được; tài liệu minh họa đầy đủ, có ảnh chụp cho từng bước, sẽ có cùng bản beta.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.window.title":"Cửa sổ","docs.copier.title":"Tạo một bản sao","docs.language.title":"Ngôn ngữ","docs.privacy.title":"Quyền riêng tư và mạng","docs.start.p1":"Flipcopy chạy bên trong DAW của bạn như một plugin CLAP, VST3 hoặc AU, hoặc chạy riêng như một ứng dụng độc lập. Đặt nó lên bất kỳ track âm thanh nào: nó cho âm thanh của track đi qua nguyên vẹn đúng như khi đến, nên để nó ở nguyên chỗ là an toàn.","docs.start.p2":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Flipcopy hiện ra thỏa thuận cấp phép của nó. Đọc đến hết, nút Đồng ý sẽ khả dụng. Cho đến khi bạn đồng ý, Flipcopy không đọc gì, không sao chép gì và không thêm gì vào âm thanh của track bạn.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Flipcopy đang mở, trong mọi DAW và trong ứng dụng độc lập. Nếu bạn từ chối, hãy chọn Đọc lại bất cứ khi nào bạn sẵn sàng.","docs.window.p1":"Một bên là trình duyệt, với trình phát nghe thử neo bên dưới nó. Phần còn lại của cửa sổ là sân khấu, nơi máy photocopy đứng. Kéo đường phân cách giữa chúng để làm trình duyệt rộng hơn hay hẹp hơn, hoặc chọn nó rồi dùng các phím mũi tên.","docs.window.p2":"Trình duyệt tệp đến ở phiên bản 0.4.0. Cho đến lúc đó, sân khấu thuộc về máy photo.","docs.copier.p1":"Thả một tệp MIDI lên máy photo — từ Explorer hoặc Finder, ở bất cứ đâu trong cửa sổ — hoặc nhấn Enter trên mặt kính trống để chọn một tệp. Máy photo in bản gốc và úp nó xuống mặt kính. Thả một tệp không bao giờ bắt đầu sao chép.","docs.copier.p2":"Nhấn phím START màu xanh, hoặc Ctrl+Enter (Cmd+Enter trên Mac). Nắp đóng lại, đèn quét, và bản sao — MIDI được chơi bằng một nhạc cụ mặc định theo nhịp độ của tệp — trượt ra khay. Esc hoặc phím STOP màu đỏ hủy nó; phím HOME màu xám dọn mặt kính.","docs.copier.p3":"Bản sao là một tệp WAV thật trong Documents/Freally Flipcopy/Copies, được đánh số, và không bao giờ bị di chuyển, ghi đè hay xóa. Nắm vào khung màu xanh chanh quanh clip đã in và kéo thẳng lên một track trong DAW của bạn. Sao chép âm thanh sang MIDI đến ở phiên bản 0.3.0.","docs.copier.p4":"Tiếng của máy photo phát nhỏ qua ngõ ra riêng của plugin, không bao giờ khi DAW đang phát và không bao giờ vào bản bounce. Tắt hoặc giảm chúng trong Cài đặt.","docs.language.p1":"Flipcopy nói được mười tám ngôn ngữ. Nó khởi động bằng ngôn ngữ hệ thống của bạn; để chọn ngôn ngữ khác, mở Cài đặt bằng biểu tượng bánh răng ở đầu trình duyệt và chọn một ngôn ngữ. Lựa chọn này áp dụng cho mọi bản Flipcopy trên máy tính.","docs.privacy.p1":"Flipcopy không có tài khoản, không có đo lường từ xa, và plugin cùng ứng dụng độc lập hoàn toàn không chứa mã mạng nào. Tệp và bản sao của bạn không bao giờ rời khỏi máy tính của bạn.","docs.privacy.p2":"Nó không chứa bất kỳ dạng AI nào: mọi bản sao đều được tạo ra bằng xử lý tín hiệu cổ điển, xác định, và một cổng kiểm tra khi dựng sẽ thất bại nếu có thư viện học máy nào từng được thêm vào.","search.placeholder":"Tìm kiếm trong tài liệu","docs.contents":"Mục lục","download.title":"Tải xuống","download.none":"Hiện chưa có gì để tải xuống, và điều đó là có chủ ý.","download.noneBody":"Không có bản beta trên trang này, không có bản dựng thử, không có quyền truy cập sớm. Flipcopy chỉ ra mắt khi mọi cổng kiểm tra đều xanh trên cả ba hệ điều hành.","download.private":"Mã nguồn của Flipcopy là riêng tư, nên cũng không có gì để tự biên dịch.","download.whenTitle":"Khi nào sẽ có","download.whenBody":"Ở phiên bản 1.0.0. Chiếc thang trên trang chủ cho thấy công việc hiện đang ở đâu.","download.ladderLink":"Con đường đến 1.0 →","search.none":"Không có gì trên trang này khớp với điều đó.","changelog.7d0a0c44680b":"Mọi thay đổi đáng chú ý của Freally Flipcopy. Chiếc thang phiên bản nằm trên trang tài liệu (“Con đường đến 1.0”); mỗi bậc là một tag. Bản dựng phát hành của mỗi bậc được đăng dưới dạng bản phát hành <strong>nháp</strong> trong kho mã nguồn này; trang tài liệu không cung cấp bản tải xuống nào cho đến <code>v1.0.0</code>.","changelog.2096d3c4bbd8":"[0.3.0] — 2026-10-01 — Âm thanh → MIDI: khoảnh khắc kỳ diệu","changelog.df6f06284fdc":"Đặt một loop âm thanh lên mặt kính, nhấn START, và MIDI của nó sẽ ra — mỗi lớp mà máy photo nghe thấy là một trang, in liền nhau từ một lần quét, mỗi trang là một tệp riêng, đóng khung xanh chanh và kéo vào DAW của bạn riêng lẻ hoặc tất cả cùng lúc. Một tệp MIDI có nhiều phần cũng ra theo cách đó: mỗi phần một trang âm thanh, và toàn bộ tệp thành một bản mix.","changelog.6b02e0d363a4":"Đã thêm","changelog.24a7fe5481b4":"<strong>Âm thanh → MIDI.</strong> Một loop âm thanh được tách thành các lớp — trống, bass, giai điệu, một <strong>đối điệu</strong> khi loop có dòng thứ hai độc lập, và hợp âm — bằng bộ trích xuất DSP cổ điển của MIDI Master (không AI). Mỗi lớp tìm thấy là một trang riêng và một tệp <code>.mid</code> riêng, đặt tên theo cách DAW hiển thị (<em>Loop - Bassline - 120 BPM - C# Minor</em>); lớp nào không có thì không có trang, và một loop hoàn toàn không có nốt nào sẽ bị từ chối thay vì sao ra trang trắng. Giọng chỉ được in khi đọc được rõ ràng.","changelog.0c3d252fc872":"<strong>Một xấp trang.</strong> Các trang lần lượt được đẩy ra từ cùng một lần quét, xòe ra trên khay, mỗi trang mang tiêu đề là dạng và phần của nó (<em>MIDI GIAI ĐIỆU</em>, <em>ÂM THANH DÒNG BASS</em>) cùng <em>TRANG n/N</em>. Nhấp vào một trang để đưa nó lên trên cùng. <strong>Chưa thể kéo gì cho đến khi trang cuối cùng đã nằm yên.</strong>","changelog.55fa665ebb50":"<strong>Hai kiểu kéo từ xấp trang đã xong.</strong> Trang trên cùng có hai thẻ xanh chanh: <strong>Tất cả phần</strong> kéo mọi trang thành các tệp riêng, để DAW xếp chúng thành mỗi lớp một track; <strong>Bản mix đầy đủ</strong> kéo một tệp chứa tất cả — một tệp <code>.mid</code> nhiều track gồm mọi phần, hoặc toàn bộ bản kết xuất dưới dạng <code>.wav</code> — được ghi cạnh các trang và không bao giờ được in. Di chuột lên thẻ để xem thông số của bản mix; khi không có con trỏ, <em>Lưu bản phối đầy đủ thành…</em> sẽ lưu nó.","changelog.7ab067eeb165":"<strong>MIDI → âm thanh, từng phần một.</strong> Một tệp MIDI có nhiều phần sẽ in mỗi phần một trang âm thanh (<em>ÂM THANH GIAI ĐIỆU</em>, <em>ÂM THANH DÒNG BASS</em>), mỗi trang được kết xuất riêng và vẽ từ tệp WAV của chính nó, cùng với Bản mix đầy đủ — tổng các phần bằng đúng bản mix, dưới cùng một mức gain headroom.","changelog.71cfe75f90c6":"<strong>Loop dài tối đa 16 ô nhịp.</strong> Mặt kính từ chối clip dài hơn và cho biết độ dài của nó tính bằng ô nhịp, không bao giờ cắt ngắn; loop một, hai hoặc bốn ô nhịp vẫn được sao chép. Số ô nhịp của một loop âm thanh được đếm theo nhịp độ mà máy photo đọc được.","changelog.6aed786b024a":"<strong>Những trang trung thực.</strong> Trang Hợp âm nói rõ đó là vòng hòa âm, không phải cách bấm đã chơi; khi có một giai điệu hát được nghe thấy và để nguyên, trang đầu tiên nói rõ điều đó, và một loop chỉ có giai điệu hát sẽ bị từ chối kèm đúng lý do ấy, chứ không phải “không có gì để sao chép”. Mọi nhịp độ được in đều ghi rõ nguồn gốc — đọc từ loop, hoặc, khi các nhát đánh của loop không khớp lưới nào, là của host, của tên tệp hoặc mặc định.","changelog.cb05cd0fc0f0":"<strong><code>flipc</code></strong>, công cụ dòng lệnh, chạy chính mặt kính và máy photo của plugin: <code>flipc copy &lt;file&gt; --out &lt;dir&gt;</code>, <code>flipc facts &lt;file&gt;</code> (khối dữ liệu đúng như trang giấy in ra), <code>flipc score</code> (bộ chấm điểm corpus) và <code>flipc bench</code> (đo thời gian).","changelog.d2365b73e8bc":"<strong>Cổng kiểm tra corpus.</strong> Corpus audioTest được chấm điểm trong mỗi lần chạy CI cục bộ có nó — và báo SKIPPED ở nơi không có — so với các mức sàn chỉ tăng lên.","changelog.2a6141e43be0":"Đã thay đổi","changelog.d2a673b21c8f":"<strong>Nhịp độ của host được theo dõi theo từng khối</strong>, và một tệp MIDI không có nhịp độ riêng sẽ được sao chép theo nhịp độ của host ngay lúc bạn nhấn START.","changelog.ee270218636c":"<strong>Nhịp độ của phiên chỉ dùng để phá thế hòa quãng tám.</strong> Một loop 120 BPM thả vào phiên 90 BPM được đọc ở 120 (bốn ô nhịp), chứ không phải 90 (ba ô nhịp) — đã sửa trong bộ trích xuất dùng chung của MIDI Master, cho mọi sản phẩm Freally có đọc loop.","changelog.ab8ac52d964e":"<strong>Hiện miễn phí, không hứa hẹn mãi mãi.</strong> Freally Flipcopy hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán. Giờ đây mọi trang của trang tài liệu đều nói rõ điều này.","changelog.7fb464e21cf8":"<strong>Kho mã đã chuyển</strong> sang tài khoản GitHub riêng của người bảo trì, ở chế độ riêng tư và Bảo lưu mọi quyền, với các crate Freally dùng chung lấy từ Freally MIDI Master và Freally Oscillate bên cạnh; địa chỉ web của plugin là địa chỉ mới của trang tài liệu.","changelog.c584da8d5dfd":"<strong>Tích hợp liên tục chạy trên máy của người bảo trì</strong> trước mỗi lần push — mọi cổng kiểm tra trên Windows, và các cổng Linux trong Docker Desktop — và không có gì chạy trên GitHub Actions. Mọi commit đều mang <code>[skip ci]</code>. (Trong vài giờ vào ngày 2026-09-30, kho mã nguồn từng công khai và CI chạy trên GitHub cho mỗi lần push.)","changelog.1246fc93bca0":"Đã sửa","changelog.79a07e8925af":"<strong>Giao diện có hồ sơ trình duyệt riêng.</strong> Dữ liệu WebView2 của Flipcopy (<code>%APPDATA%\\Freally Flipcopy\\webview</code>) trước đây bị lưu trong thư mục của Freally MIDI Master, và hai sản phẩm dùng chung một hồ sơ WebView2 có thể khiến giao diện của nhau bị trống khi cả hai chạy trong cùng một DAW. Giờ đây nó thuộc riêng Flipcopy.","changelog.72de476110e3":"<strong>Bản mix đầy đủ của một bản sao chỉ có thể là tệp của chính nó</strong>: một <code>record.json</code> bị sửa sau lưng máy photo không thể trỏ thao tác kéo, Lưu thành hay Hiện trong thư mục đến bất kỳ chỗ nào khác.","changelog.427549a6dab4":"<strong>Một bản sao được ghi trọn vẹn hoặc không ghi gì cả.</strong> Mọi trang và bản mix đều nằm trên đĩa trước khi bất kỳ tệp nào nhận tên của nó, nên một lỗi giữa chừng không bao giờ để lại các trang trong một thư mục đánh số mà không bản sao nào sở hữu.","changelog.2604a6288e96":"<strong>Không trang nào bị clip.</strong> Mức gain headroom duy nhất được xác định theo mọi tệp mà một bản sao ghi ra — một phần có thể có đỉnh cao hơn bản mix ở chỗ các phần khác triệt tiêu nó.","changelog.c6cb2c38dd63":"<strong>Một loop 16 ô nhịp được xuất dài thừa một tick vẫn là 16 ô nhịp</strong>, không phải 17 — một nốt cuối được nhả quá vạch nhịp một nốt móc ba không phải là một ô nhịp riêng.","changelog.2ba628500475":"<strong>Controller đến được trang in</strong> ngay cả trên một kênh không phát nốt nào.","changelog.833039ba4e85":"[0.2.0] — 2026-09-30 — Máy photocopy và bản sao đầu tiên","changelog.35409a92a233":"Máy photo đứng trên sân khấu, diễn lại các phân cảnh của những video câu chuyện máy photo dựng bằng Blender theo đúng thứ tự: thả một tệp MIDI lên mặt kính, nhấn START màu xanh lá, và một bản sao âm thanh thật trượt ra khay — in từ chính tệp của nó, đóng khung xanh chanh, và kéo thẳng vào DAW của bạn.","changelog.c12f4045ef96":"<strong>Máy photo trên sân khấu.</strong> Cỗ máy được kết xuất từ cùng cảnh Blender với hai video câu chuyện — phần đế, nắp máy dưới dạng các khung sprite, các phím được nhấn, các matte của mặt kính và khay — được kết xuất trên chính nền của cửa sổ (<code>#090c09</code>) trên phim trong suốt, nên nó đứng trong căn phòng mà không có đường nối nào. Các giai đoạn là các phân cảnh của video theo đúng thứ tự trong video (tờ giấy lật lại và úp xuống, nắp máy đóng lại kèm cú nảy, tiếng bíp START, đèn quét qua lại, rò ánh xanh lơ ra khe phía trước trong khi cả căn phòng tối dần, bản sao trượt ra khay), với thời lượng ngắn hơn của bản cắt trong ứng dụng; một bài kiểm thử sẽ thất bại nếu ứng dụng phát một phân cảnh mà câu chuyện không có, bỏ qua một phân cảnh, hoặc phát sai thứ tự. Nó lấp đầy mọi khoảng trống mà cửa sổ dành cho nó và không bao giờ bị lật gương trong ngôn ngữ viết từ phải sang trái.","changelog.81d392181aa1":"<strong>Nút START xanh lá là cách kích hoạt duy nhất.</strong> Thả một clip chỉ đặt nó lên mặt kính. START (hoặc <code>Ctrl/Cmd+Enter</code>, nhấn đúng phím đó) bắt đầu sao chép; STOP (hoặc <code>Esc</code>) hủy giữa lúc quét mà không để lại gì; HOME dọn mặt kính. Phím mang chữ <em>START</em> đặt xiên, quay về phía bảng cảm ứng, và đèn LED của nó sáng mỗi khi có thể bắt đầu sao chép. Một bài kiểm thử plugin gửi mọi lệnh và thất bại nếu bất kỳ lệnh nào ngoài <code>copier_start</code> khởi động một tác vụ, và một cổng kiểm tra khi dựng sẽ thất bại nếu trang từng gửi lệnh đó từ bất cứ đâu ngoài phím START.","changelog.3c73db8b1385":"<strong>Mặt kính.</strong> Thả một tệp âm thanh hoặc MIDI từ Explorer hoặc Finder vào bất cứ đâu trên cửa sổ (mặt kính sáng lên khi tệp tới), hoặc nhấn <code>Enter</code> trên mặt kính trống để chọn một tệp. Tệp được đọc trên một luồng riêng và được in ngửa trước khi đặt xuống — nốt thật hoặc dạng sóng thật, cùng thông số riêng của tệp. Đường dẫn mạng, tệp quá lớn, quá dài, im lặng, bị hỏng, tính giờ SMPTE và tệp MIDI định dạng 2 đều bị từ chối, mỗi loại bằng một câu riêng. Hai tệp cùng lúc: tệp đầu tiên được đặt lên, và máy báo mỗi lần chỉ một clip. Một clip mới thả lên một bản sao đã xong cũng được đặt lên mặt kính như vậy, và khay được dọn trống (bản sao vẫn nằm trong thư mục Bản sao). Một tệp bị mặt kính từ chối sẽ để nguyên clip đang nằm trên đó.","changelog.4267b3fd96ac":"<strong>MIDI → âm thanh.</strong> Bản sao kết xuất các nốt của tệp qua một toner mặc định — chính các tiếng preset của MIDI Master cho các phần có cao độ, và một drum machine, mỗi làn GM một tiếng, cho phần trống — tôn trọng pitch bend và pedal sustain (của kênh nào chỉ áp dụng cho nốt của kênh đó), với đuôi 2.5 s, theo nhịp độ của tệp (nếu không có thì của host — ứng dụng độc lập không có — nếu không thì nhịp độ trong tên tệp, nếu không nữa thì 120 — và trang in ghi rõ là nguồn nào), giữ dưới −0.3 dBFS, và ghi thành tệp WAV 24-bit ở tần số mẫu của host (44.1 kHz trong ứng dụng độc lập) mà DAW đặt khớp lưới phách. Một bản sao dài tối đa bằng độ dài mà một trang có thể in — năm phút, hoặc 2:30 khi trên 48 kHz — và bản dài hơn sẽ bị từ chối trước khi kết xuất, không bao giờ bị cắt ngắn. Âm thanh → MIDI sẽ đến ở <code>v0.3.0</code>; trước đó, nhấn START với một clip âm thanh sẽ được báo thẳng thắn như vậy.","changelog.d9714ba71fa5":"<strong>Thư mục Bản sao</strong> (<code>Documents/Freally Flipcopy/Copies</code>): mỗi bản sao một thư mục đánh số, được giành một cách nguyên tử để hai DAW không bao giờ dùng chung một số; các trang được đặt tên theo cách DAW hiển thị (<code>Title - Part - 120 BPM, Key.wav</code>); mọi trang đều được ghi nguyên tử, đọc lại và xác minh — và <strong>không bao giờ bị di chuyển, ghi đè hay xóa</strong>, vì DAW của bạn tham chiếu nó qua đường dẫn.","changelog.48b3f94d470b":"<strong>Bản in, từ chính các tệp.</strong> Mọi trang — bản gốc trên mặt kính và bản sao trong khay — đều được in laser giống các bản in trong video câu chuyện: tiêu đề, dòng nguồn, thước ô nhịp, piano roll với làn lực nhấn hoặc dạng sóng với <strong>dải phổ</strong> mới, và khối dữ liệu, tất cả đều do plugin tính từ các byte trên đĩa. Một ô nhịp có số chỉ nhịp lẻ giữ nguyên nửa phách của nó (7/8 in ba phách rưỡi mỗi ô nhịp). Trang của bản sao ghi rõ những gì bản kết xuất đã bỏ ra — các controller nó không phát, các nốt trống mà bộ trống không có tiếng — không bao giờ lặng lẽ bỏ qua. Một bài kiểm thử đọc cấu trúc các trang của ứng dụng và của chính các bản in trong video rồi đối chiếu chúng với nhau.","changelog.fa6958b17901":"<strong>Kéo bản sao vào DAW của bạn.</strong> Trang được đẩy ra mang một khung xanh chanh quanh clip, bên dưới có dòng <em>Kéo vào DAW</em> — chính khung là tay nắm. Nhấn bên trong khung và di chuyển 4 px, tệp của chính bản sao sẽ được kéo (kèm một bản in nhỏ trên con trỏ) vào FL Studio, Ableton, Reaper hoặc bất kỳ DAW nào nhận tệp. Không thể kéo gì cho đến khi trang ra hết; ở nơi không thể kéo, khung chuyển sang màu xám, nét đứt và đề xuất Lưu thành thay thế. Nhấn <code>Enter</code> trên trang sẽ mở Lưu thành hoặc hiện tệp trong thư mục của nó.","changelog.4da7005c5000":"<strong>Tiếng máy</strong>, được tổng hợp từ đầu cho chiếc máy photo này (đặt bản gốc, nắp, tiếng bíp, bắt đầu quét, một tiếng rè cho mỗi lượt đèn quét, đẩy trang ra) và được plugin trộn vào ngõ ra riêng của nó — không bao giờ qua thẻ HTML <code>&lt;audio&gt;</code> — ở mức −18 dB qua mức Monitor, im lặng khi DAW đang phát (ứng dụng độc lập không có transport DAW nào để phải im lặng), im lặng khi bounce ngoại tuyến, và không bao giờ thay thế âm thanh của track. Trong Cài đặt có bật/tắt, âm lượng, và lựa chọn “Im lặng khi DAW đang phát”.","changelog.f8fc9e0d2e58":"<strong>Màn hình cảm ứng</strong> cho biết máy đang làm gì, clip nó đang giữ, và mọi lời từ chối bằng ngôn ngữ của nhà sản xuất nhạc.","changelog.1a5ee7d7aabc":"<strong>Các cổng kiểm tra</strong> cho tất cả những điều đó, mỗi cổng đều được chứng kiến thất bại trước khi được tin dùng: bộ ba khớp nền (màu của bản kết xuất bằng đúng các token; ΔE2000 quanh hình bóng alpha của chính cỗ máy ở mọi giai đoạn với DPR 1 và 2; không có gì được vẽ giữa cỗ máy và nền), cổng START (tĩnh, plugin và Playwright), sự tương đồng bản in, các điểm ảnh của khung kéo, và các spec mới của nhánh ứng dụng chạy trong ứng dụng độc lập thật.","changelog.66b1e687636a":"<strong>Mã dùng chung</strong>: <code>freally-extract</code> (cửa giải mã và phân tích âm thanh), <code>freally-encode</code> (WAV, lấy mẫu lại, các đoạn khớp lưới DAW) và <code>freally-drag</code> (nguồn kéo gốc của hệ điều hành) được dùng từ MIDI Master ở <code>shared-v5</code>, cùng với <code>freally_library::audition::NoteRenderer</code>, các sự kiện controller của <code>read_facts</code>, và hook thả tệp của bộ điều hợp web view, việc đặt lại vị trí web view khi cửa sổ di chuyển và thanh tiêu đề trống của nó — tất cả được thêm ở thượng nguồn tại đó.","changelog.e7908191194e":"<strong>Biểu tượng là của chính chủ sở hữu</strong> — chữ <em>F</em> xanh chanh trên nền dạng sóng và piano roll — trên tệp thực thi, các gói plugin, biểu tượng Linux và macOS và trang tài liệu, thay cho biểu tượng tạm.","changelog.719f74499130":"<strong>Cửa sổ.</strong> Thanh tiêu đề của ứng dụng độc lập mang biểu tượng, tối màu và cùng màu với căn phòng, và không ghi gì cả: không có tiêu đề trên thanh tiêu đề của ứng dụng độc lập hay của cửa sổ plugin trong một DAW mà chú thích đã nêu tên Flipcopy, vì tên đang xoay ở phía trên cửa sổ đã nói điều đó. Tên xoay ấy lớn gấp đôi để đọc được trong nháy mắt, và được căn giữa phía máy photo của cửa sổ; bên cạnh đó, trình duyệt tệp chạy từ đỉnh cửa sổ xuống đến khu nghe thử.","changelog.120afa46c010":"Cầu nối nhận yêu cầu tới 2 MiB (một ảnh kéo); <code>host_info</code> cho biết ở đây có thể kéo trang hay không.","changelog.df29ffbf7480":"Trước khi thỏa thuận cấp phép được chấp nhận, trang chỉ có thể đọc ngôn ngữ giao diện và không gì khác, qua một lệnh riêng (<code>locale_get</code>); <code>prefs_get</code> chỉ trả lời khi thỏa thuận đã được chấp nhận.","changelog.bf4a28a43b62":"<strong>Di chuyển cửa sổ trên màn hình có tỉ lệ co giãn.</strong> Khi Windows được đặt ở 150%, kéo cửa sổ ứng dụng độc lập bằng thanh tiêu đề khiến nội dung bị vẽ lệch về phía sau cửa sổ một phần ba quãng đường, về phía góc trên bên trái màn hình, che mất mép phải và mép dưới cho đến khi cửa sổ được đưa về lại góc đó. Giờ đây nội dung luôn nằm đúng dưới cửa sổ dù nó được di chuyển đi đâu.","changelog.f246f03536b6":"<strong>Ứng dụng độc lập ở đúng tỉ lệ màn hình của bạn.</strong> Trên màn hình có tỉ lệ co giãn (150%), ứng dụng độc lập chạy như một chương trình kiểu cũ, không co giãn: Windows kéo giãn cửa sổ của nó trong khi trang bên trong vẽ theo điểm ảnh thật — gốc rễ của các lỗi lệch vị trí khi kéo và ở danh sách thả xuống được liệt kê ở đây. Giờ đây nó tự khai báo nhận biết DPI theo từng màn hình trước khi mở cửa sổ, giống ứng dụng độc lập của Freally MIDI Master và Freally Unloop, nên trang được vẽ sắc nét theo tỉ lệ màn hình và cửa sổ mở ra đúng kích thước dự định.","changelog.4d43aa80977a":"<strong>Danh sách ngôn ngữ mở ngay dưới ô của nó.</strong> Trên màn hình có tỉ lệ co giãn, danh sách thả xuống của hệ thống mở lệch xuống dưới và sang phải ô trong Cài đặt, ô càng xa góc cửa sổ thì lệch càng xa; giờ đây danh sách do chính Flipcopy vẽ, ngay dưới ô, theo phong cách tối của cửa sổ, và mỗi ngôn ngữ được viết bằng chữ viết của riêng nó.","changelog.a348e37f07eb":"[0.1.0] — 2026-09-26 — Nền móng &amp; xương sống CI","changelog.8847996db9e9":"Sản phẩm trống mà mọi bậc sau đều xây dựng trên đó: nó tải được, cho âm thanh đi qua nguyên vẹn, hỏi về thỏa thuận cấp phép, mở cửa sổ tối của nó, và mọi cổng kiểm tra chất lượng đều chạy.","changelog.cc29ebe17a90":"<strong>Plugin, mọi định dạng từ một tệp nhị phân.</strong> Một plugin CLAP nih-plug với các điểm vào VST3 và AUv2 do <code>clap-wrapper</code> tạo ra (sạch về giấy phép: không dùng binding VST3 GPL), cùng <strong>ứng dụng độc lập</strong> — một ứng dụng desktop gốc có cửa sổ và thiết bị âm thanh riêng, không bao giờ là ứng dụng web. Âm thanh stereo vào và ra, một đầu vào nốt cho tính năng “Quét từ track” sau này, độ trễ bằng không, và âm thanh của track được cho đi qua <strong>nguyên từng bit</strong> (một bài kiểm tra null chứng minh điều đó). Một công tắc <strong>Bypass</strong> của host và một mức <strong>Monitor</strong> cho âm thanh mà chính Flipcopy sẽ thêm vào (tiếng máy và nghe thử, từ <code>v0.2.0</code>) — nó không bao giờ chạm vào track. Một trạng thái lưu có phiên bản, được giới hạn kích thước, được chuyển đổi khi nâng cấp và bị từ chối toàn bộ thay vì tải một nửa, nên một dự án bị hỏng không bao giờ làm sập host.","changelog.59616adfaedb":"<strong>Thỏa thuận cấp phép</strong> (<code>EULA.md</code>, có cấu trúc giống của Freally Oscillate) và cổng kiểm tra của nó: Flipcopy yêu cầu bạn chấp nhận ở lần mở đầu tiên và không làm gì cho đến khi bạn đồng ý — nó không đọc gì, không sao chép gì và không thêm gì vào track của bạn. Thỏa thuận được biên dịch vào plugin và được phục vụ từ đó, nút Đồng ý chờ cho đến khi văn bản được đọc đến hết, và câu trả lời của bạn được dùng chung cho mọi bản đang mở và ứng dụng độc lập. Một lần từ chối không lưu được sẽ báo rõ điều đó.","changelog.ed5631790156":"<strong>Cửa sổ</strong>, mở ở kích thước 1400 × 875 (kích thước của Freally Unloop) và co giãn đồng bộ đến mọi kích thước — mọi thứ giữ nguyên tỉ lệ, không có dải viền nào quanh nó — bên dưới một thanh tiêu đề nơi <em>Freally Flipcopy</em> và số phiên bản xoay quanh trục Y theo kiểu 3D, giống như của Freally Oscillate và Freally MIDI Master (và đứng yên khi bật giảm chuyển động): lớp vỏ tối với thanh trình duyệt và khu nghe thử ở phía đầu dòng, một thanh chia có thể kéo (260–420 px, dùng được cả phím mũi tên), và sân khấu — không có nền riêng, để máy photo sẽ đứng trong căn phòng mà không có đường nối nào xung quanh. Một chủ đề duy nhất, tối, và không có gì có thể tạo ra chủ đề thứ hai.","changelog.ccf91016802f":"<strong>Mười tám ngôn ngữ</strong> cho mọi thứ trong cửa sổ, lựa chọn được lưu theo từng máy tính và dùng chung cho mọi bản đang chạy; bố cục từ phải sang trái cho tiếng Ả Rập.","changelog.92d766745704":"<strong>Phông chữ Noto của Google</strong>, được đóng gói kèm theo giấy phép SIL Open Font License 1.1, với tệp giấy phép đi kèm bên cạnh.","changelog.b502e66ba7a3":"<strong>Trang tài liệu</strong>, được xây dựng giống trang của Freally Oscillate và chỉ có giao diện tối, bằng cùng mười tám ngôn ngữ (mỗi ngôn ngữ chỉ được tải khi người đọc chọn): trang chủ với chiếc thang phiên bản (được tạo từ <code>docs/ladder.json</code> và được một cổng kiểm tra giữ khớp với kế hoạch nội bộ), hai câu chuyện máy photo dựng bằng Blender trong “Xem nó sao chép”, tài liệu, nhật ký thay đổi này, và một trang tải xuống nói thẳng rằng chưa có gì để tải trước <code>v1.0.0</code>. Các câu chuyện phát kèm âm thanh, chỉ khi bạn nhấn chữ START xiên trên phím xanh lá của máy photo (hoặc nút phát), và dừng lại ở khung hình đầu tiên khi kết thúc hoặc bị dừng; câu chuyện âm thanh → MIDI in mỗi lớp một trang — MIDI Giai điệu, MIDI Hợp âm, MIDI Dòng bass và MIDI Đối điệu — lần lượt lên một xấp trong khay, mỗi trang đóng khung xanh chanh với <em>Kéo vào DAW</em> bên dưới.","changelog.96a59e69b7f8":"<strong>Văn bản luôn nằm gọn trong khung chứa</strong> ở cả 18 ngôn ngữ, ở cửa sổ mặc định và cửa sổ nhỏ nhất (một bước kiểm tra Playwright trên mọi nhãn).","changelog.495bcdf8956e":"<strong>Các cổng kiểm tra</strong>, mỗi cổng đều được chứng kiến thất bại trước khi được tin dùng: định dạng mã, clippy, mọi bài kiểm thử, kiểm tra kiểu, lint, cổng ngôn ngữ (18 danh mục, khóa và placeholder giống hệt nhau, thật sự được dịch), lint CSS logic, design token và độ tương phản, chỉ giao diện tối, danh sách cấm (không AI, không mạng, không đo lường từ xa), kiểm tra giấy phép, cổng crate dùng chung (dùng lại, không bao giờ fork), tên sản phẩm (không bao giờ dùng thương hiệu của hãng sản xuất máy photo), độ lệch binding, chiếc thang, không có bản tải xuống trước 1.0, ngân sách tài nguyên, <code>clap-validator</code> và <code>pluginval</code> ở mức nghiêm ngặt 10, CI cục bộ trên Windows và trong Docker cho Linux, và Playwright trên hai nhánh — trình duyệt và cửa sổ ứng dụng độc lập thật.","changelog.8f6fb4eb7f42":"Bảo mật","changelog.09dd8d0ea4e1":"Giao diện chỉ tải trang đã được biên dịch vào tệp nhị phân, dưới một Content Security Policy nghiêm ngặt; cầu nối của nó chỉ trả lời yêu cầu JSON <code>POST</code> của chính trang đó, từ chối mọi thứ trên 64 KiB và mọi đường dẫn chứa <code>..</code>, và trước khi thỏa thuận được chấp nhận thì chỉ trả lời một danh sách lệnh được cho phép. Bản dựng phát hành không mở DevTools và không mở cổng gỡ lỗi từ xa.","changelog.e06fbd4d3359":"Không có mã mạng trong plugin hay ứng dụng độc lập, được trình biên dịch (<code>clippy.toml</code>) và đồ thị phụ thuộc (<code>scripts/check-denylist.mjs</code>) kiểm tra.","changelog.70e17daefb45":"Các tệp mà Flipcopy lưu trong thư mục dữ liệu ứng dụng của bạn (câu trả lời cho thỏa thuận và các tùy chọn) được đọc với giới hạn kích thước và được ghi nguyên tử, nên một tệp bị hỏng hoặc bị sửa tay sẽ được tải như giá trị mặc định và một sự cố không bao giờ để lại nửa tệp."};
